"use client";
import { useEffect, useRef, useState } from "react";
import { motion } from "motion/react";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryIndex,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface IndexWipeItem extends GalleryInternalItem {}
export interface IndexWipeProps extends GalleryInternalProps {
  items: readonly IndexWipeItem[];
  duration?: number;
  dim?: number;
}
export function IndexWipe(props: IndexWipeProps) {
  const {
    items,
    duration = 0.85,
    dim = 0.45,
    height = 640,
    label = "Chapter index",
    className = "",
    style,
    onSelect,
  } = props;
  const env = useGalleryEnvironment();
  const { current, choose } = useGalleryIndex(props);
  const last = useRef(current);
  const [transition, setTransition] = useState({ previous: current, direction: 1 });
  useEffect(() => {
    if (last.current !== current) {
      setTransition({ previous: last.current, direction: current > last.current ? 1 : -1 });
      last.current = current;
    }
  }, [current]);
  const direction =
    current === last.current ? transition.direction : current > last.current ? 1 : -1;
  const previous = current === last.current ? transition.previous : last.current;
  const clip =
    direction > 0
      ? "polygon(0% 0%,100% 0%,100% 0%,0% -8%)"
      : "polygon(0% 108%,100% 100%,100% 100%,0% 100%)";
  return (
    <div
      ref={env.ref}
      className={`z-ag ${className}`}
      data-gallery="index-wipe"
      data-index={current}
      data-direction={direction}
      role="region"
      aria-label={label}
      style={galleryStyle(height, { background: "#111", color: "#fff", ...style })}
    >
      <GalleryInternalStyles />
      {items[previous] && (
        <GalleryInternalImage item={items[previous]} style={{ position: "absolute", inset: 0 }} />
      )}
      {items[current] && (
        <motion.div
          key={items[current].id}
          className="z-ag-wipe"
          initial={{ clipPath: clip }}
          animate={{ clipPath: "polygon(0% 0%,100% 0%,100% 100%,0% 100%)" }}
          transition={{ duration: env.reduced ? 0 : duration, ease: [0.76, 0, 0.24, 1] }}
          style={{ position: "absolute", inset: 0 }}
        >
          <GalleryInternalImage item={items[current]} />
        </motion.div>
      )}
      <div style={{ position: "absolute", inset: 0, background: `rgba(0,0,0,${dim})` }} />
      <span style={{ position: "absolute", right: 28, top: 30, fontSize: 13 }}>Index</span>
      <nav
        aria-label={label}
        style={{
          position: "absolute",
          left: "3.2%",
          top: "12%",
          bottom: "12%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
        }}
      >
        {items.map((item, i) => (
          <button
            type="button"
            key={item.id}
            data-gallery-card={i}
            aria-current={current === i ? "true" : undefined}
            onPointerEnter={(e) => {
              if (e.pointerType !== "touch") choose(i);
            }}
            onFocus={() => choose(i)}
            onClick={() => {
              choose(i);
              onSelect?.(item, i);
            }}
            style={{
              padding: 0,
              border: 0,
              background: "none",
              fontSize: "clamp(34px,6.7vw,88px)",
              lineHeight: 1.15,
              letterSpacing: "-.04em",
              fontWeight: 400,
              textAlign: "left",
              color: current === i ? "#fff" : "#ffffff50",
              cursor: "pointer",
              transition: `color ${duration / 2}s`,
            }}
          >
            {item.title}
          </button>
        ))}
      </nav>
      <div
        style={{
          position: "absolute",
          bottom: 28,
          left: "3.2%",
          fontSize: 13,
          display: "flex",
          gap: 4,
          overflow: "hidden",
          height: 16,
        }}
      >
        <motion.span
          key={current}
          initial={{ y: direction * 18 }}
          animate={{ y: 0 }}
          transition={{ duration: env.reduced ? 0 : duration }}
        >
          {String(current + 1).padStart(2, "0")}
        </motion.span>
        <span style={{ opacity: 0.5 }}>/ {String(items.length).padStart(2, "0")}</span>
      </div>
    </div>
  );
}
